function tightestRange(lists: number[][]): number[] {
  let best = [0, Infinity];
  for (const list of lists) for (const a of list) {
    let b = a, ok = true;
    for (const l of lists) {
      let lo = 0, hi = l.length; // first index with l[i] >= a
      while (lo < hi) { const m = (lo + hi) >> 1; if (l[m] < a) lo = m + 1; else hi = m; }
      if (lo === l.length) { ok = false; break; }
      b = Math.max(b, l[lo]);
    }
    if (ok && (b - a < best[1] - best[0] || (b - a === best[1] - best[0] && a < best[0]))) best = [a, b];
  }
  return best;
}

