class MinHeap {
  private a: number[][] = [];
  get size() { return this.a.length; }
  push(x: number[]): void {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (a[p][0] <= a[i][0]) break; [a[p], a[i]] = [a[i], a[p]]; i = p; }
  }
  pop(): number[] {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1; let m = i;
        if (l < a.length && a[l][0] < a[m][0]) m = l;
        if (r < a.length && a[r][0] < a[m][0]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

function tightestRange(lists: number[][]): number[] {
  const heap = new MinHeap();
  let hi = -Infinity;
  lists.forEach((l, i) => { heap.push([l[0], i, 0]); hi = Math.max(hi, l[0]); });
  let best = [0, Infinity];
  for (;;) {
    const [lo, li, idx] = heap.pop();
    if (hi - lo < best[1] - best[0]) best = [lo, hi];
    if (idx + 1 === lists[li].length) return best;
    const next = lists[li][idx + 1];
    hi = Math.max(hi, next);
    heap.push([next, li, idx + 1]);
  }
}

